def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    if len(bins) == 0:
        return np.array([])
    max_cap = np.max(bins)
    ratio = np.where(max_cap > 0, rem / max_cap, 0.0)
    scores = np.where(rem >= 0, -np.power(ratio + 1.0, 3.0), -np.inf)
    empty_mask = (bins == max_cap) & (rem >= 0)
    if np.any(empty_mask):
        first_empty = np.argmax(empty_mask)
        scores[first_empty] = -2.0
    return scores
